import XCTest
import Foundation
@testable import ScannerCore

// Golden vectors generated by the C# app (v2/tests/QuanLyHangHoan.Tests/GoldenSaleworkVectorsTests.cs):
// cloud/golden/salework-vectors.json. The Swift port must reproduce them exactly.

/// Order-preserving JSON value (numbers keep their raw text, like C# GetRawText).
indirect enum GoldenJSON {
    case null
    case bool(Bool)
    case number(String)
    case string(String)
    case array([GoldenJSON])
    case object([(String, GoldenJSON)])

    subscript(key: String) -> GoldenJSON? {
        if case .object(let pairs) = self { return pairs.first(where: { $0.0 == key })?.1 }
        return nil
    }

    var arrayValue: [GoldenJSON] {
        if case .array(let a) = self { return a }
        return []
    }

    var stringValue: String? {
        if case .string(let s) = self { return s }
        return nil
    }

    var intValue: Int? {
        if case .number(let n) = self { return Int(n) ?? Double(n).map { Int($0) } }
        return nil
    }

    /// Same as Str() in the C# generator: string -> itself, number -> raw text, bool -> "true"/"false", else "".
    var cellText: String {
        switch self {
        case .string(let s): return s
        case .number(let n): return n
        case .bool(let b): return b ? "true" : "false"
        default: return ""
        }
    }

    var short: String {
        switch self {
        case .null: return "null"
        case .bool(let b): return b ? "true" : "false"
        case .number(let n): return n
        case .string(let s): return "\"\(s)\""
        case .array(let a): return "[\(a.count) items]"
        case .object(let o): return "{\(o.map { $0.0 }.joined(separator: ","))}"
        }
    }
}

struct GoldenJSONParser {
    struct ParseError: Error { let message: String }

    private let b: [UInt8]
    private var i = 0

    private init(_ data: Data) { b = [UInt8](data) }

    static func parse(_ data: Data) throws -> GoldenJSON {
        var p = GoldenJSONParser(data)
        if p.b.count >= 3 && p.b[0] == 0xEF && p.b[1] == 0xBB && p.b[2] == 0xBF { p.i = 3 }
        let v = try p.value()
        p.ws()
        guard p.i == p.b.count else { throw ParseError(message: "trailing data at \(p.i)") }
        return v
    }

    private mutating func ws() {
        while i < b.count, b[i] == 0x20 || b[i] == 0x09 || b[i] == 0x0A || b[i] == 0x0D { i += 1 }
    }

    private func peek() -> UInt8? { i < b.count ? b[i] : nil }

    private mutating func expect(_ s: String) throws {
        for c in s.utf8 {
            guard i < b.count, b[i] == c else { throw ParseError(message: "expected \(s) at \(i)") }
            i += 1
        }
    }

    private mutating func value() throws -> GoldenJSON {
        ws()
        guard let c = peek() else { throw ParseError(message: "unexpected end") }
        switch c {
        case UInt8(ascii: "{"):
            i += 1
            var pairs: [(String, GoldenJSON)] = []
            ws()
            if peek() == UInt8(ascii: "}") { i += 1; return .object(pairs) }
            while true {
                ws()
                let k = try string()
                ws()
                try expect(":")
                let v = try value()
                pairs.append((k, v))
                ws()
                if peek() == UInt8(ascii: ",") { i += 1; continue }
                try expect("}")
                return .object(pairs)
            }
        case UInt8(ascii: "["):
            i += 1
            var items: [GoldenJSON] = []
            ws()
            if peek() == UInt8(ascii: "]") { i += 1; return .array(items) }
            while true {
                items.append(try value())
                ws()
                if peek() == UInt8(ascii: ",") { i += 1; continue }
                try expect("]")
                return .array(items)
            }
        case UInt8(ascii: "\""):
            return .string(try string())
        case UInt8(ascii: "t"):
            try expect("true"); return .bool(true)
        case UInt8(ascii: "f"):
            try expect("false"); return .bool(false)
        case UInt8(ascii: "n"):
            try expect("null"); return .null
        default:
            let start = i
            while i < b.count, let ch = peek(),
                  (ch >= 0x30 && ch <= 0x39) || ch == UInt8(ascii: "-") || ch == UInt8(ascii: "+") || ch == UInt8(ascii: ".")
                    || ch == UInt8(ascii: "e") || ch == UInt8(ascii: "E") {
                i += 1
            }
            guard i > start else { throw ParseError(message: "bad value at \(i)") }
            return .number(String(decoding: b[start..<i], as: UTF8.self))
        }
    }

    private mutating func hex4() throws -> UInt32 {
        guard i + 4 <= b.count else { throw ParseError(message: "bad \\u escape") }
        var v: UInt32 = 0
        for _ in 0..<4 {
            let c = b[i]
            i += 1
            v <<= 4
            switch c {
            case 0x30...0x39: v |= UInt32(c - 0x30)
            case 0x41...0x46: v |= UInt32(c - 0x41 + 10)
            case 0x61...0x66: v |= UInt32(c - 0x61 + 10)
            default: throw ParseError(message: "bad hex digit")
            }
        }
        return v
    }

    private mutating func string() throws -> String {
        try expect("\"")
        var out: [UInt8] = []
        func appendScalar(_ v: UInt32) {
            let scalar = Unicode.Scalar(v) ?? "\u{FFFD}"
            out.append(contentsOf: Array(String(Character(scalar)).utf8))
        }
        while true {
            guard i < b.count else { throw ParseError(message: "unterminated string") }
            let c = b[i]
            i += 1
            if c == UInt8(ascii: "\"") { break }
            if c != UInt8(ascii: "\\") { out.append(c); continue }
            guard i < b.count else { throw ParseError(message: "bad escape") }
            let e = b[i]
            i += 1
            switch e {
            case UInt8(ascii: "\""): out.append(0x22)
            case UInt8(ascii: "\\"): out.append(0x5C)
            case UInt8(ascii: "/"): out.append(0x2F)
            case UInt8(ascii: "b"): out.append(0x08)
            case UInt8(ascii: "f"): out.append(0x0C)
            case UInt8(ascii: "n"): out.append(0x0A)
            case UInt8(ascii: "r"): out.append(0x0D)
            case UInt8(ascii: "t"): out.append(0x09)
            case UInt8(ascii: "u"):
                let hi = try hex4()
                if hi >= 0xD800 && hi <= 0xDBFF, i + 1 < b.count, b[i] == UInt8(ascii: "\\"), b[i + 1] == UInt8(ascii: "u") {
                    i += 2
                    let lo = try hex4()
                    if lo >= 0xDC00 && lo <= 0xDFFF {
                        appendScalar(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
                    } else {
                        appendScalar(0xFFFD); appendScalar(lo)
                    }
                } else {
                    appendScalar(hi)
                }
            default:
                throw ParseError(message: "bad escape \\\(e)")
            }
        }
        return String(decoding: out, as: UTF8.self)
    }
}

enum GoldenSupport {
    /// Tests/ScannerCoreTests/X.swift -> ScannerCore -> ios-app -> repo root.
    static func repoRoot(_ file: String = #filePath) -> URL {
        URL(fileURLWithPath: file)
            .deletingLastPathComponent() // ScannerCoreTests
            .deletingLastPathComponent() // Tests
            .deletingLastPathComponent() // ScannerCore
            .deletingLastPathComponent() // ios-app
            .deletingLastPathComponent() // repo root
    }

    static func golden(_ name: String) -> URL {
        repoRoot().appendingPathComponent("cloud").appendingPathComponent("golden").appendingPathComponent(name)
    }

    static func load(_ name: String) throws -> GoldenJSON {
        try GoldenJSONParser.parse(Data(contentsOf: golden(name)))
    }

    /// Rows() of the C# generator: objects only, values via Str().
    static func rows(_ v: GoldenJSON?) -> [SaleworkRow] {
        guard let v = v else { return [] }
        return v.arrayValue.compactMap { r -> SaleworkRow? in
            guard case .object(let pairs) = r else { return nil }
            return SaleworkRow(pairs.map { ($0.0, $0.1.cellText) })
        }
    }

    /// Compares two row lists as dictionaries (count + every key/value). Optionally checks key order too.
    static func diffRows(_ expected: [SaleworkRow], _ actual: [SaleworkRow], path: String, checkOrder: Bool = false, into diffs: inout [String]) {
        if expected.count != actual.count {
            diffs.append("\(path): row count expected \(expected.count), got \(actual.count)")
            return
        }
        for (n, pair) in zip(expected, actual).enumerated() {
            let (e, a) = pair
            let ed = e.dictionary, ad = a.dictionary
            for k in e.keys {
                let av = ad[k]
                if av != ed[k] {
                    diffs.append("\(path)[\(n)][\"\(k)\"]: expected \"\(ed[k] ?? "")\", got \(av.map { "\"\($0)\"" } ?? "missing")")
                }
            }
            for k in a.keys where ed[k] == nil {
                diffs.append("\(path)[\(n)]: unexpected key \"\(k)\" = \"\(ad[k] ?? "")\"")
            }
            if checkOrder && e.keys != a.keys {
                diffs.append("\(path)[\(n)]: key order expected \(e.keys), got \(a.keys)")
            }
        }
    }

    /// Deep JSON comparison: objects unordered, numbers numeric, null strict.
    static func diffJSON(_ e: GoldenJSON, _ a: GoldenJSON, path: String, into diffs: inout [String]) {
        switch (e, a) {
        case (.null, .null): return
        case (.bool(let x), .bool(let y)):
            if x != y { diffs.append("\(path): expected \(x), got \(y)") }
        case (.number(let x), .number(let y)):
            if Double(x) != Double(y) { diffs.append("\(path): expected \(x), got \(y)") }
        case (.string(let x), .string(let y)):
            if x != y { diffs.append("\(path): expected \"\(x)\", got \"\(y)\"") }
        case (.array(let x), .array(let y)):
            if x.count != y.count {
                diffs.append("\(path): array count expected \(x.count), got \(y.count) (expected \(x.map { $0.short }), got \(y.map { $0.short }))")
                return
            }
            for (n, pair) in zip(x, y).enumerated() { diffJSON(pair.0, pair.1, path: "\(path)[\(n)]", into: &diffs) }
        case (.object(let x), .object(let y)):
            var ay: [String: GoldenJSON] = [:]
            for (k, v) in y { ay[k] = v }
            var ex = Set<String>()
            for (k, v) in x {
                ex.insert(k)
                if let av = ay[k] { diffJSON(v, av, path: "\(path).\(k)", into: &diffs) } else { diffs.append("\(path).\(k): missing (expected \(v.short))") }
            }
            for (k, v) in y where !ex.contains(k) { diffs.append("\(path).\(k): unexpected (\(v.short))") }
        default:
            diffs.append("\(path): expected \(e.short), got \(a.short)")
        }
    }

    /// The parcel exactly as it would be POSTed (JSONSerialization), parsed back.
    static func parcelJSON(_ p: SaleworkParcel) -> GoldenJSON? {
        let obj = p.incomingJSON()
        guard JSONSerialization.isValidJSONObject(obj), let data = try? JSONSerialization.data(withJSONObject: obj, options: []) else { return nil }
        return try? GoldenJSONParser.parse(data)
    }
}

final class SaleworkVectorsTests: XCTestCase {
    func testSaleworkVectorsMatchCSharp() throws {
        let root = try GoldenSupport.load("salework-vectors.json")
        let cases = root["cases"]?.arrayValue ?? []
        XCTAssertGreaterThanOrEqual(cases.count, 40, "need the golden cases")

        var failedCases = 0
        for c in cases {
            let name = c["name"]?.stringValue ?? "?"
            let input = GoldenSupport.rows(c["input"]?["rows"])
            guard let expected = c["expected"] else { XCTFail("\(name): no expected"); continue }
            var diffs: [String] = []

            let prepared: SaleworkPrepared
            do {
                prepared = try SaleworkImport.prepare(rows: input, todayYear: 2026)
            } catch {
                XCTFail("\(name): threw \(error)")
                failedCases += 1
                continue
            }

            GoldenSupport.diffRows(GoldenSupport.rows(expected["clean"]), prepared.clean, path: "clean", into: &diffs)
            let expDup = expected["duplicateCount"]?.intValue ?? -1
            if expDup != prepared.duplicateCount { diffs.append("duplicateCount: expected \(expDup), got \(prepared.duplicateCount)") }

            let expIds = (expected["orderIds"]?.arrayValue ?? []).map { $0.cellText }
            if expIds != prepared.orderIds { diffs.append("orderIds: expected \(expIds), got \(prepared.orderIds)") }

            let expGroups = expected["groups"]?.arrayValue ?? []
            if expGroups.count != prepared.groups.count {
                diffs.append("groups: count expected \(expGroups.count), got \(prepared.groups.count)")
            } else {
                for (gi, pair) in zip(expGroups, prepared.groups).enumerated() {
                    let (eg, ag) = pair
                    GoldenSupport.diffRows(GoldenSupport.rows(eg["rows"]), ag.rows, path: "groups[\(gi)].rows", into: &diffs)
                    let es = eg["skipped"]?.intValue ?? -1
                    if es != ag.skipped { diffs.append("groups[\(gi)].skipped: expected \(es), got \(ag.skipped)") }
                    let ef = eg["failedDelivery"]?.intValue ?? -1
                    if ef != ag.failedDelivery { diffs.append("groups[\(gi)].failedDelivery: expected \(ef), got \(ag.failedDelivery)") }
                    let ep = eg["parcels"]?.arrayValue ?? []
                    if ep.count != ag.parcels.count {
                        diffs.append("groups[\(gi)].parcels: count expected \(ep.count), got \(ag.parcels.count) (orderIds got \(ag.parcels.map { $0.orderId }))")
                    } else {
                        for (pi, pp) in zip(ep, ag.parcels).enumerated() {
                            guard let aj = GoldenSupport.parcelJSON(pp.1) else {
                                diffs.append("groups[\(gi)].parcels[\(pi)]: not serializable")
                                continue
                            }
                            GoldenSupport.diffJSON(pp.0, aj, path: "groups[\(gi)].parcels[\(pi)]", into: &diffs)
                        }
                    }
                }
            }

            if !diffs.isEmpty {
                failedCases += 1
                XCTFail("\(name): \(diffs.count) difference(s):\n" + diffs.prefix(10).joined(separator: "\n"))
            }
        }
        XCTAssertEqual(failedCases, 0, "\(failedCases) of \(cases.count) Salework cases differ from C#")
    }

    func testPrepareWithDateUsesItsYear() throws {
        var comps = DateComponents()
        comps.year = 2026; comps.month = 11; comps.day = 23; comps.hour = 12
        let date = Calendar(identifier: .gregorian).date(from: comps) ?? Date()
        let rows = [SaleworkRow([("Mã đơn hàng", "ORD-1"), ("Trạng thái", "ĐANG HOÀN"), ("Mã vận đơn", "840000000009"),
                                 ("Tên sản phẩm trên sàn", "Áo"), ("Số lượng", "1"), ("Ngày tạo đơn", "10/11"), ("Số điện thoại", "0900000000")])]
        let prepared = try SaleworkImport.prepare(rows: rows, today: date)
        XCTAssertEqual(prepared.clean.first?.keys.contains("Số điện thoại"), false)
        XCTAssertEqual(prepared.orderIds, ["ORD-1"])
        XCTAssertEqual(prepared.parcels.count, 1)
        XCTAssertEqual(prepared.parcels.first?.shipDate, "10/11/2026")
        XCTAssertEqual(prepared.parcels.first?.carrier, "J&T Express")
        XCTAssertTrue(JSONSerialization.isValidJSONObject(prepared.incomingJSON))
    }

    func testInvalidQuantityThrowsLikeCSharp() {
        let rows = [SaleworkRow([("Mã đơn hàng", "ORD-1"), ("Trạng thái", "ĐANG HOÀN"), ("Mã vận đơn", "840000000009"), ("Số lượng", "1.5")])]
        XCTAssertThrowsError(try SaleworkImport.prepare(rows: rows, todayYear: 2026)) { error in
            XCTAssertEqual((error as? SaleworkImportError)?.message, "Số lượng không hợp lệ: 1.5. Cần số nguyên không âm.")
        }
    }

    func testTextHelpersMirrorDotNet() {
        XCTAssertEqual(SWText.trim("\u{00A0} a b \u{3000}"), "a b")
        XCTAssertEqual(SWText.key("Mã Đơn hàng (ID)"), "madonhangid")
        XCTAssertEqual(SWText.normalizeScientificOrderId("5.87069307928479E+17"), "587069307928479000")
        XCTAssertEqual(SWText.parseMoney("138.580"), 138580)
        XCTAssertEqual(SWText.parseMoney("138580.00"), 138580)
        XCTAssertEqual(try SWText.parseQuantity("1,000"), 1000)
        XCTAssertEqual(try SWText.parseQuantity("2.00"), 2)
        XCTAssertEqual(SWText.extractDate("2026-11-10 08:00:00", 2026), "10/11/2026 08:00")
        XCTAssertEqual(SWText.cleanTrackingCode(" spxvn0123456789 "), "SPXVN0123456789")
        XCTAssertEqual(SWText.split("a - b", #"\s*\-\s*"#), ["a", "b"])
        XCTAssertTrue(SWText.isMatch(#"^\s$"#, "\u{0085}"))
    }
}
